def jaro_winkler(a,b):
    import math
    # compute jaro then winkler
    def jaro_inner(a,b):
        a_len=len(a); b_len=len(b)
        if a_len==0 and b_len==0: return 1.0
        elif a_len==0 or b_len==0: return 0.0
        sr=max(a_len,b_len)//2
        sr=max(0,sr-1)
        af=[False]*a_len; bf=[False]*b_len; m=0
        for i,ca in enumerate(a):
            mn=max(0,i-sr); mx=min(b_len,i+sr+1)
            for j in range(mn,mx):
                if not bf[j] and ca==b[j]:
                    af[i]=True; bf[j]=True; m+=1; break
        if m==0: return 0.0
